```python
import hmac, hashlib, time

def verify_webhook(raw_body: bytes, ts_hdr: str, sig_hdr: str, secret: bytes) -> bool:
    try:
        ts = int(ts_hdr)
    except ValueError:
        return False
    if abs(int(time.time()) - ts) > 300:
