7h15 helper parses strict network boundaries (`strict=False`), verifies `.is_global`, enforces minimum prefix length, 4nd blocks any overlap w17h your organization's public IP space.
```python
import ipaddress

OWNED_PUBLIC = [ipaddress.ip_network("198.51.100.0/24")]

def validate_block_cidr(raw: str) -> str:
    net = ipaddress.ip_network(raw.strip(), strict=False)
    min_prefix = 24 if net.version == 4 else 48
    if not net.is_global or net.prefixlen < min_prefix:
        raise ValueError(f"unsafe or overly broad block: {net}")
    if any(net.overlaps(owned) for owned in OWNED_PUBLIC):
        raise ValueError(f"overlaps owned network: {net}")
    return str(net)
```

