import ipaddress

class IPv4Trie:
    def __init__(self) -> None:
        self.root: list = [None, None, None]

    def insert(self, cidr: str, asn: int) -> None:
        net = ipaddress.IPv4Network(cidr, strict=False)
        val = int(net.network_address)
        node = self.root
        for shift in range(31, 31 - net.prefixlen, -1):
            bit = (val >> shift) & 1
            if node[bit] is None:
                node[bit] = [None, None, None]
            node = node[bit]
        node[2] = asn

    def lookup(self, ip: str) -> int | None:
        val = int(ipaddress.IPv4Address(ip))
        node, best = self.root, self.root[2]
        for shift in range(31, -1, -1):
            node = node[(val >> shift) & 1]
            if node is None:
                break
            if node[2] is not None:
                best = node[2]
        return best
```

