bool walk_macho_cmds(const uint8_t *img, size_t img_len) {
    if (img_len < sizeof(struct mach_header_64)) return false;
    struct mach_header_64 mh;
    memcpy(&mh, img, sizeof(mh));
    if (mh.sizeofcmds > img_len - sizeof(mh)) return false;
    size_t end = sizeof(mh) + mh.sizeofcmds;
    size_t off = sizeof(mh);
