Fixed with explicit bounds, all definite widths, and canonical minimal-length rules:
```python
def read_bstr(buf: bytes, off: int) -> tuple[bytes, int]:
    if off >= len(buf) or (buf[off] >> 5) != 2:
        raise ValueError("expected CBOR bstr")
    info = buf[off] & 0x1F
    widths = {24: (1, 24), 25: (2, 256), 26: (4, 65536), 27: (8, 4294967296)}
    if info < 24:
        ln, pos = info, off + 1
    elif info in widths:
        w, min_v = widths[info]
        if off + 1 + w > len(buf):
            raise ValueError("truncated header")
        ln = int.from_bytes(buf[off + 1:off + 1 + w], "big")
        if ln < min_v:
            raise ValueError("non-canonical CBOR length")
        pos = off + 1 + w
    else:
        raise ValueError("indefinite or reserved CBOR info")
    if pos + ln > len(buf):
        raise ValueError("truncated CBOR payload")
    return buf[pos:pos + ln], pos + ln
```

