import json

def validate_json_schema(raw: str, max_depth: int = 6) -> dict:
    if len(raw.encode("utf-8")) > 16384:
        raise ValueError("schema exceeds 16KB")
    obj = json.loads(raw)
    def _walk(node, depth: int) -> None:
        if depth > max_depth:
            raise ValueError("schema nesting too deep")
        if isinstance(node, dict):
            if "$ref" in node:
                raise ValueError("$ref not permitted")
            pat = node.get("pattern", "")
            if isinstance(pat, str) and len(pat) > 128:
                raise ValueError("pattern too long")
            for v in node.values():
                _walk(v, depth + 1)
        elif isinstance(node, list):
            for item in node:
                _walk(item, depth + 1)
    _walk(obj, 0)
    return obj
```

