```python
import unicodedata

BIDI_CHARS = frozenset(chr(c) for c in (*range(0x202A, 0x202F), *range(0x2066, 0x206A)))

def clean_chunk(text: str) -> str:
    norm = unicodedata.normalize("NFKC", text)
    out = []
    for ch in norm:
        cp = ord(ch)
        if 0xE0000 <= cp <= 0xE007F or ch in BIDI_CHARS or cp in (0x00AD, 0x200B, 0xFEFF):
            continue
        if ch not in ("\n", "\t") and unicodedata.category(ch) in ("Cc", "Cs", "Co"):
            continue
        out.append(ch)
    return "".join(out).strip()
